const NODES = ['n1','n2','n3'];
function compareVC(a, b) {
  let aLeq = true, bLeq = true, eq = true;
  for (const k of NODES) {
    const av = a[k] || 0, bv = b[k] || 0;
    if (av > bv) aLeq = false;
    if (bv > av) bLeq = false;
    if (av !== bv) eq = false;
  }
  if (eq) return 'equal';
  if (aLeq) return 'before';
  if (bLeq) return 'after';
  return 'concurrent';
}
const pairs = [
  [{n1:1,n2:0,n3:0}, {n1:2,n2:1,n3:0}],
  [{n1:2,n2:2,n3:1}, {n1:1,n2:2,n3:0}],
  [{n1:1,n2:2,n3:0}, {n1:2,n2:1,n3:0}],
  [{n1:3,n2:1,n3:4}, {n1:3,n2:1,n3:4}],
];
for (const [a, b] of pairs) console.log(compareVC(a, b));
